template <TemplateMC2TypeA2Class>
__aicore__ inline void MoeDistributeDispatchA2<TemplateMC2TypeA2Func>::WaitDispatch()
{
    if (unlikely(needPerformanceInfo_)) {
        // 避免没有被分配任务的核未初始化performanceInfoI32Tensor_
        Duplicate<int32_t>(performanceInfoI32Tensor_, 0, performanceInfoSize_ * sizeof(int64_t) / sizeof(int32_t));
        SyncFunc<AscendC::HardEvent::V_S>();
    }

    if (worldTaskInfo_.taskNum == 0) {
        SyncAll<true>();
        return;
    }

    DataCopyExtParams copyFlagParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
    DataCopyPadExtParams<int32_t> padParams{false, 0, 0, 0};
    auto dataFlagLocal =
        LocalTensor<int32_t>{TPosition::LCM, statusTensor_.GetSize() * sizeof(int32_t), BITS32_PER_BLOCK};
    auto taskQueue =
        LocalTensor<int32_t>{TPosition::LCM, static_cast<uint32_t>(dataFlagLocal.GetPhyAddr()) + dataFlagLocal.GetSize() * static_cast<uint32_t>(sizeof(int32_t)), worldTaskInfo_.taskNum};
    auto addrQueue =
        LocalTensor<uint64_t>{TPosition::LCM, static_cast<uint32_t>(taskQueue.GetPhyAddr()) + taskQueue.GetSize() * static_cast<uint32_t>(sizeof(int32_t)), worldTaskInfo_.taskNum};
    for (uint32_t taskId = 0; taskId < worldTaskInfo_.taskNum; ++taskId) {
        taskQueue(taskId) = taskId + worldTaskInfo_.startTaskId;
    }
    SyncFunc<AscendC::HardEvent::S_MTE2>();

    uint32_t recvFlagNum = 0;
    uint32_t unArrivedNum = worldTaskInfo_.taskNum;
    int32_t index = -1;
    int64_t startTime = GetCurrentTimestampUs();
    while (unArrivedNum > 0) {
        ++ index;
        if (index >= unArrivedNum) {
            index = 0;
        }
        uint32_t rankId = taskQueue(index);
        SyncFunc<AscendC::HardEvent::S_MTE2>();
        DataCopy(statusTensor_[rankId * statusEntryCount_], windowInstatusTensor_[rankId * dataSizePerRank_ / sizeof(int32_t)], statusEntryCount_);
        SyncFunc<AscendC::HardEvent::MTE2_S>();
        int32_t statusFlag = statusTensor_(rankId * statusEntryCount_ + statusEntryCount_ - 1);
        if (statusFlag != FLAG_VALUE) {
            continue;
        }
        uint32_t tokenCount = 0;
        for (int32_t expertOffset = 0; expertOffset < localMoeExpertNum_; expertOffset++) {
            tokenCount += statusTensor_(rankId * statusEntryCount_ + expertOffset);
        }
        uint64_t dataFlagOffset = (rankId * dataSizePerRank_ + DATA_OFFSET + tokenCount * hCommuSize_ + SKIP_OFFSET) / sizeof(int32_t);
        DataCopyPad(dataFlagLocal, windowInstatusTensor_[dataFlagOffset], copyFlagParams, padParams);
        int32_t dataFlag = dataFlagLocal(0);
        if (dataFlag != FLAG_VALUE) {
            continue;
        }
        if (unlikely(needPerformanceInfo_)) {
            auto srcRankId = rankId;
            RecordRankCommDuration(performanceInfoI32Tensor_, srcRankId, startTime);
        }
        addrQueue(unArrivedNum - 1) = dataFlagOffset;
        taskQueue(index) = taskQueue(unArrivedNum - 1);
        taskQueue(unArrivedNum - 1) = rankId;
        -- unArrivedNum;
        -- index;
    }

    for (uint32_t taskId = 0; taskId < worldTaskInfo_.taskNum; ++taskId) {
        windowInstatusTensor_(taskQueue(taskId)) = 0;
    }
    SyncAll<true>();
}`

# DataCopy
`template <TemplateMC2TypeA2Class>
__aicore__ inline void MoeDistributeDispatchA2<TemplateMC2TypeA2Func>::WaitDispatch()
{
    if (unlikely(needPerformanceInfo_)) {
        // 避免没有被分配任务的核未初始化performanceInfoI32Tensor_
        Duplicate<int32_t>(performanceInfoI32Tensor_, 0, performanceInfoSize_ * sizeof(int64_t) / sizeof(int32_t));
        SyncFunc<AscendC::HardEvent::V_S>();
    }

    if (worldTaskInfo_.taskNum == 0) {
        SyncAll<true>();
        return;
    }

    DataCopyExtParams copyFlagParams{1, static_cast<uint32_t>(sizeof(int32_t)), 0, 0, 0};
    DataCopyPadExtParams<int32_t> padParams{false, 0, 0, 0};
    auto dataFlagLocal =
        LocalTensor<int32_t>{TPosition::LCM, statusTensor_.GetSize() * sizeof(int32_t), BITS32_PER_BLOCK};
    auto isVisited =
        LocalTensor<bool>{TPosition::LCM, statusTensor_.GetSize() * sizeof(int32_t) + dataFlagLocal.GetSize() * sizeof(int32_t), RoundUp(worldTaskInfo_.taskNum, UB_ALIGN)};
    auto &&isVisitedU32 = isVisited.template ReinterpretCast<uint32_t>();
    uint32_t tokenCountAddr = isVisited.GetPhyAddr() + isVisited.GetSize() * sizeof(bool);
    auto tokenCountLT =
        LocalTensor<int32_t>{TPosition::LCM, tokenCountAddr, RoundUp(worldTaskInfo_.taskNum, BITS32_PER_BLOCK)};
    Duplicate<uint32_t>(isVisitedU32, uint32_t(0), isVisitedU32.GetSize());
    Duplicate<int32_t>(tokenCountLT, -1, tokenCountLT.GetSize());
    SyncFunc<AscendC::HardEvent::V_S>();
    SyncFunc<AscendC::HardEvent::S_MTE2>();

    uint32_t recvFlagNum = 0;
    int64_t startTime = GetCurrentTimestampUs();
    while (recvFlagNum < worldTaskInfo_.taskNum) {
        for (uint32_t rankId = worldTaskInfo_.startTaskId; rankId < worldTaskInfo_.endTaskId; rankId++) {
            DataCopy(statusTensor_[rankId * statusEntryCount_], windowInstatusTensor_[rankId * dataSizePerRank_ / sizeof(int32_t)], statusEntryCount_);
            SyncFunc<AscendC::HardEvent::MTE2_S>();
            int32_t statusFlag = statusTensor_(rankId * statusEntryCount_ + statusEntryCount_ - 1);
            if (statusFlag != FLAG_VALUE) {
                continue;
            }
            uint32_t tokenCount = 0;
            for (int32_t expertOffset = 0; expertOffset < localMoeExpertNum_; expertOffset++) {
                tokenCount += statusTensor_(rankId * statusEntryCount_ + expertOffset);
            }
            uint64_t dataFlagOffset = (rankId * dataSizePerRank_ + DATA_OFFSET + tokenCount * hCommuSize_ + SKIP_OFFSET) / sizeof(int32_t);
            DataCopyPad(dataFlagLocal, windowInstatusTensor_[dataFlagOffset], copyFlagParams, padParams);
            SyncFunc<AscendC::HardEvent::MTE2_S>();
            int32_t dataFlag = dataFlagLocal(0);
            if (dataFlag != FLAG_VALUE) {
                continue;
            }
            assert(!isVisited(rankId - worldTaskInfo_.startTaskId), "[CurrentRank:%d] Double Visited Rank:%d, tokenCount:[%d/%d].\n", rankId_, rankId, tokenCountLT(rankId - worldTaskInfo_.startTaskId), tokenCount);
            isVisited(rankId - worldTaskInfo_.startTaskId) = true;
            tokenCountLT(rankId - worldTaskInfo_.startTaskId) = static_cast<int32_t>(tokenCount);
            recvFlagNum++;
            dataFlagLocal(0) = 0;
            SyncFunc<AscendC::HardEvent::S_MTE3>();
            DataCopyPad(windowInstatusTensor_[dataFlagOffset], dataFlagLocal, copyFlagParams);
            SyncFunc<AscendC::HardEvent::MTE3_MTE2>();
            if (unlikely(needPerformanceInfo_)) {
                auto srcRankId = rankId;
                RecordRankCommDuration(performanceInfoI32Tensor_, srcRankId, startTime);
            }
        }
    }
    SyncAll<true>();
}`

